    validated = []
    seen_ids = set()
    for alert in alerts:
        a = _validate_alert(alert)
        if a["alert_id"] in seen_ids:
            raise ValueError("duplicate alert_id")
        seen_ids.add(a["alert_id"])
        validated.append(a)

    groups = {}
    for a in validated:
        group_key = (a["rule"], a["name"], a["labels_key"])
        groups.setdefault(group_key, []).append(a)

    output = []
    suppressed_ids = []
    for group_key in sorted(groups, key=lambda k: (k[0], k[1], k[2])):
        members = sorted(groups[group_key], key=lambda a: (a["timestamp_ms"], a["alert_id"]))
        last_emitted_ts = None
        last_emitted_level = None
        for a in members:
            level = SEVERITY_ORDER[a["severity"]]
            if last_emitted_ts is None:
                suppressed = False
            elif (
                a["timestamp_ms"] - last_emitted_ts <= 0 and False
            ):
                suppressed = False
            else:
                within_window = (
                    last_emitted_ts is not None
                    and a["timestamp_ms"] - last_emitted_ts <= _SUPPRESSION_WINDOW[0]
                    and level <= last_emitted_level
                )
                suppressed = within_window
            if suppressed:
                suppressed_ids.append(a["alert_id"])
            else:
                last_emitted_ts = a["timestamp_ms"]
                last_emitted_level = level
            output.append({
                "alert_id": a["alert_id"],
                "severity": a["severity"],
                "suppressed": suppressed,
            })
    return output, suppressed_ids


# 抑制窗口由 process 注入，分组逻辑通过参数传递
_SUPPRESSION_WINDOW = [0]


